  ('dictation', '{"text": "My brother works at a bank."}'::jsonb, '{"exact": "My brother works at a bank."}'::jsonb, 'A1', 0.1, 'approved', 'styled-v2', 'practice'),
  ('dictation', '{"text": "We eat dinner at seven o''clock."}'::jsonb, '{"exact": "We eat dinner at seven o''clock."}'::jsonb, 'A1', 0.1, 'approved', 'styled-v2', 'practice'),
  ('dictation', '{"text": "She bought a new phone last week."}'::jsonb, '{"exact": "She bought a new phone last week."}'::jsonb, 'A2', 0.25, 'approved', 'styled-v2', 'practice'),
  ('dictation', '{"text": "Although it was raining, we decided to go for a walk."}'::jsonb, '{"exact": "Although it was raining, we decided to go for a walk."}'::jsonb, 'B1', 0.45, 'approved', 'styled-v2', 'practice'),
  ('dictation', '{"text": "He has been working here since he graduated."}'::jsonb, '{"exact": "He has been working here since he graduated."}'::jsonb, 'B1', 0.45, 'approved', 'styled-v2', 'practice'),
  ('dictation', '{"text": "The proposal was rejected because it lacked sufficient detail."}'::jsonb, '{"exact": "The proposal was rejected because it lacked sufficient detail."}'::jsonb, 'B2', 0.65, 'approved', 'styled-v2', 'practice'),
  ('dictation', '{"text": "Had the committee been informed earlier, the decision might have been reconsidered."}'::jsonb, '{"exact": "Had the committee been informed earlier, the decision might have been reconsidered."}'::jsonb, 'C1', 0.8, 'approved', 'styled-v2', 'practice'),
  ('dictation', '{"text": "Despite widespread skepticism, the initiative ultimately proved remarkably successful."}'::jsonb, '{"exact": "Despite widespread skepticism, the initiative ultimately proved remarkably successful."}'::jsonb, 'C1', 0.8, 'approved', 'styled-v2', 'practice'),
  ('dictation', '{"text": "The nuances of the negotiation were lost on those unfamiliar with the underlying politics."}'::jsonb, '{"exact": "The nuances of the negotiation were lost on those unfamiliar with the underlying politics."}'::jsonb, 'C2', 0.95, 'approved', 'styled-v2', 'practice'),
  ('dictation', '{"text": "Notwithstanding the board''s reservations, the merger proceeded largely unimpeded."}'::jsonb, '{"exact": "Notwithstanding the board''s reservations, the merger proceeded largely unimpeded."}'::jsonb, 'C2', 0.95, 'approved', 'styled-v2', 'practice'),
