  ('reading', '{"text": "My name is Anna. I live in a small house near the park."}'::jsonb, NULL::jsonb, 'A1', 0.1, 'approved', 'styled-v2', 'practice'),
  ('reading', '{"text": "The bus comes at eight o''clock every morning."}'::jsonb, NULL::jsonb, 'A1', 0.1, 'approved', 'styled-v2', 'practice'),
  ('reading', '{"text": "I usually walk to work, but when it rains, I take the bus instead."}'::jsonb, NULL::jsonb, 'A2', 0.25, 'approved', 'styled-v2', 'practice'),
  ('reading', '{"text": "Our team has a meeting every Monday morning to plan the week."}'::jsonb, NULL::jsonb, 'A2', 0.25, 'approved', 'styled-v2', 'practice'),
  ('reading', '{"text": "Learning a new language takes time and patience. Many people give up too early because they expect quick results."}'::jsonb, NULL::jsonb, 'B1', 0.45, 'approved', 'styled-v2', 'practice'),
  ('reading', '{"text": "The company announced that it would be relocating its headquarters next year, a decision that surprised many long-term employees."}'::jsonb, NULL::jsonb, 'B2', 0.65, 'approved', 'styled-v2', 'practice'),
  ('reading', '{"text": "Researchers found that people who exercise regularly tend to report higher levels of overall life satisfaction."}'::jsonb, NULL::jsonb, 'B2', 0.65, 'approved', 'styled-v2', 'practice'),
  ('reading', '{"text": "While the report acknowledged significant progress, it also highlighted several areas where the organization had fallen noticeably short of its original targets."}'::jsonb, NULL::jsonb, 'C1', 0.8, 'approved', 'styled-v2', 'practice'),
  ('reading', '{"text": "The debate over remote work has grown increasingly polarized, with some executives insisting on a full return to the office and others championing flexibility as the future of productive work."}'::jsonb, NULL::jsonb, 'C1', 0.8, 'approved', 'styled-v2', 'practice'),
  ('reading', '{"text": "It would be disingenuous to suggest that the reforms, however well-intentioned, have not exacted a considerable toll on those least equipped to weather the transition."}'::jsonb, NULL::jsonb, 'C2', 0.95, 'approved', 'styled-v2', 'practice'),
  ('reading', '{"text": "Skeptics have long dismissed the initiative as little more than a public relations exercise, yet even they concede that its unintended consequences have been far more consequential than anyone anticipated."}'::jsonb, NULL::jsonb, 'C2', 0.95, 'approved', 'styled-v2', 'practice'),
  ('reading_comprehension', '{"passage": "The store opens at 9am and closes at 6pm.", "question": "What time does the store open?", "options": ["8am", "9am", "10am", "6pm"]}'::jsonb, '{"correctIndex": 1}'::jsonb, 'A1', 0.1, 'approved', 'styled-v2', 'practice'),
  ('reading_comprehension', '{"passage": "Maria has two cats and one dog.", "question": "How many pets does Maria have?", "options": ["One", "Two", "Three", "Four"]}'::jsonb, '{"correctIndex": 2}'::jsonb, 'A1', 0.1, 'approved', 'styled-v2', 'practice'),
  ('reading_comprehension', '{"passage": "The train to the city leaves every hour, but the last one is at 11pm.", "question": "When is the last train?", "options": ["9pm", "10pm", "11pm", "Midnight"]}'::jsonb, '{"correctIndex": 2}'::jsonb, 'A2', 0.25, 'approved', 'styled-v2', 'practice'),
  ('reading_comprehension', '{"passage": "David forgot his umbrella, so he got wet walking home in the rain.", "question": "Why did David get wet?", "options": ["He fell in a puddle", "He forgot his umbrella", "He washed his car", "He went swimming"]}'::jsonb, '{"correctIndex": 1}'::jsonb, 'A2', 0.25, 'approved', 'styled-v2', 'practice'),
  ('reading_comprehension', '{"passage": "The gym offers a discount for members who sign up for a full year instead of paying month by month.", "question": "How can a member get a discount?", "options": ["Bring a friend", "Pay monthly", "Sign up for a year", "Visit every day"]}'::jsonb, '{"correctIndex": 2}'::jsonb, 'B1', 0.45, 'approved', 'styled-v2', 'practice'),
  ('reading_comprehension', '{"passage": "The restaurant is fully booked on Friday and Saturday nights, but tables are usually available during the week.", "question": "When are tables usually available?", "options": ["Friday nights", "Saturday nights", "Weekend nights", "Weekdays"]}'::jsonb, '{"correctIndex": 3}'::jsonb, 'B1', 0.45, 'approved', 'styled-v2', 'practice'),
  ('reading_comprehension', '{"passage": "Although the new policy was designed to reduce paperwork, many employees reported that it actually created more administrative work in the short term.", "question": "What was the actual short-term effect of the policy?", "options": ["It reduced paperwork as planned", "It had no effect", "It created more administrative work", "It was cancelled immediately"]}'::jsonb, '{"correctIndex": 2}'::jsonb, 'B2', 0.65, 'approved', 'styled-v2', 'practice'),
  ('reading_comprehension', '{"passage": "The survey showed that customer satisfaction had improved overall, even though complaints about delivery times had increased slightly.", "question": "What increased slightly, according to the survey?", "options": ["Overall satisfaction", "Complaints about delivery times", "The number of customers", "Product quality"]}'::jsonb, '{"correctIndex": 1}'::jsonb, 'B2', 0.65, 'approved', 'styled-v2', 'practice'),
  ('reading_comprehension', '{"passage": "Critics argue that the proposed regulation, while aimed at protecting small businesses, would in practice disproportionately burden the very companies it intends to help, due to the high cost of compliance.", "question": "What is the critics'' main concern about the regulation?", "options": ["It doesn''t protect small businesses at all", "Compliance costs would burden the businesses it''s meant to help", "Large companies would benefit unfairly", "It has no clear aim"]}'::jsonb, '{"correctIndex": 1}'::jsonb, 'C1', 0.8, 'approved', 'styled-v2', 'practice'),
  ('reading_comprehension', '{"passage": "The board''s decision to postpone the merger was driven less by financial concerns than by a growing unease about cultural incompatibility between the two organizations.", "question": "What mainly drove the board''s decision?", "options": ["Financial concerns", "Legal issues", "Cultural incompatibility", "Shareholder pressure"]}'::jsonb, '{"correctIndex": 2}'::jsonb, 'C1', 0.8, 'approved', 'styled-v2', 'practice'),
  ('reading_comprehension', '{"passage": "It would be an oversimplification to attribute the company''s downturn solely to market conditions; internal mismanagement, long dismissed by the board as a minor factor, played an equally decisive role.", "question": "According to the passage, what role did internal mismanagement play?", "options": ["It played no role at all", "It was the sole cause", "It played an equally decisive role alongside market conditions", "It was only a minor factor, as the board claimed"]}'::jsonb, '{"correctIndex": 2}'::jsonb, 'C2', 0.95, 'approved', 'styled-v2', 'practice'),
  ('reading_comprehension', '{"passage": "The committee''s reluctance to act was less a matter of indecision than a calculated wager that inaction would, paradoxically, prove more politically expedient than intervention.", "question": "What does the passage suggest about the committee''s reluctance to act?", "options": ["It was simple indecisiveness", "It was a deliberate, calculated choice", "It was caused by lack of information", "It was forced by external pressure"]}'::jsonb, '{"correctIndex": 1}'::jsonb, 'C2', 0.95, 'approved', 'styled-v2', 'practice'),
  ('short_answer', '{"question": "Is a banana yellow or blue?"}'::jsonb, '{"acceptable_answers": ["yellow", "it is yellow", "it''s yellow"]}'::jsonb, 'A1', 0.1, 'approved', 'styled-v2', 'practice'),
  ('short_answer', '{"question": "Do you drink coffee in the morning or at night?"}'::jsonb, '{"acceptable_answers": ["morning", "in the morning"]}'::jsonb, 'A2', 0.25, 'approved', 'styled-v2', 'practice'),
  ('short_answer', '{"question": "Is Saturday a weekday or a weekend day?"}'::jsonb, '{"acceptable_answers": ["weekend", "weekend day", "it is a weekend day"]}'::jsonb, 'A2', 0.25, 'approved', 'styled-v2', 'practice'),
  ('short_answer', '{"question": "Sam missed his flight. Did he arrive on time or late?"}'::jsonb, '{"acceptable_answers": ["late", "he arrived late"]}'::jsonb, 'B1', 0.45, 'approved', 'styled-v2', 'practice'),
  ('short_answer', '{"question": "The shop raised its prices. Did things get cheaper or more expensive?"}'::jsonb, '{"acceptable_answers": ["more expensive", "they got more expensive"]}'::jsonb, 'B1', 0.45, 'approved', 'styled-v2', 'practice'),
  ('short_answer', '{"question": "The project was delayed due to a lack of funding. Was the delay caused by a technical problem or a financial one?"}'::jsonb, '{"acceptable_answers": ["a financial one", "financial", "it was a financial problem"]}'::jsonb, 'B2', 0.65, 'approved', 'styled-v2', 'practice'),
  ('short_answer', '{"question": "The merger fell through after regulators raised antitrust concerns. Did the deal collapse because of financial trouble or regulatory objections?"}'::jsonb, '{"acceptable_answers": ["regulatory objections", "regulatory concerns", "because of regulators"]}'::jsonb, 'C1', 0.8, 'approved', 'styled-v2', 'practice'),
  ('short_answer', '{"question": "Despite record profits, the CEO resigned amid allegations of misconduct. Was the resignation due to poor performance or personal wrongdoing?"}'::jsonb, '{"acceptable_answers": ["personal wrongdoing", "misconduct", "allegations of misconduct"]}'::jsonb, 'C1', 0.8, 'approved', 'styled-v2', 'practice'),
  ('short_answer', '{"question": "The policy was quietly shelved not because it lacked merit, but because it lacked political appetite. Was the policy abandoned for practical reasons or for a lack of political will?"}'::jsonb, '{"acceptable_answers": ["lack of political will", "political reasons", "lack of political appetite"]}'::jsonb, 'C2', 0.95, 'approved', 'styled-v2', 'practice'),
  ('short_answer', '{"question": "The settlement was reached only after both parties recognized that prolonged litigation would cost more than any potential victory. Did they settle because one side was clearly right, or because litigation was too costly?"}'::jsonb, '{"acceptable_answers": ["because litigation was too costly", "litigation was too costly", "cost of litigation"]}'::jsonb, 'C2', 0.95, 'approved', 'styled-v2', 'practice');
